import{_ as t,o as e,c as a,ah as i}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"강의 공부 과정 (1회독)","description":"","frontmatter":{"tags":["Study-Methods"],"date":"2026-10-11T00:00:00.000Z","date_created":"2026-10-11T00:00:00.000Z"},"headers":[{"level":2,"title":"1. 자료 준비","slug":"_1-자료-준비","link":"#_1-자료-준비","children":[]},{"level":2,"title":"2. 헷갈리는 개념 하나씩 질문하기","slug":"_2-헷갈리는-개념-하나씩-질문하기","link":"#_2-헷갈리는-개념-하나씩-질문하기","children":[]},{"level":2,"title":"3. 정리 파일 저장","slug":"_3-정리-파일-저장","link":"#_3-정리-파일-저장","children":[]},{"level":2,"title":"4. 큰 흐름 잡기","slug":"_4-큰-흐름-잡기","link":"#_4-큰-흐름-잡기","children":[]},{"level":2,"title":"5. 내 말로 요약하고 고치기 (반복)","slug":"_5-내-말로-요약하고-고치기-반복","link":"#_5-내-말로-요약하고-고치기-반복","children":[]},{"level":2,"title":"6. 마무리","slug":"_6-마무리","link":"#_6-마무리","children":[]}],"relativePath":"Study-Methods/01-Lecture-Study-1st-Pass.md","filePath":"Study-Methods/01-Lecture-Study-1st-Pass.md"}'),r={name:"Study-Methods/01-Lecture-Study-1st-Pass.md"};function o(s,l,n,u,d,h){return e(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="강의-공부-과정-1회독" tabindex="-1">강의 공부 과정 (1회독) <a class="header-anchor" href="#강의-공부-과정-1회독" aria-label="Permalink to &quot;강의 공부 과정 (1회독)&quot;">​</a></h1><p>1회독 진행 방식. 다른 과목에도 같은 순서로 적용한다.</p><h2 id="_1-자료-준비" tabindex="-1">1. 자료 준비 <a class="header-anchor" href="#_1-자료-준비" aria-label="Permalink to &quot;1. 자료 준비&quot;">​</a></h2><ul><li>강의자료를 텍스트로 뽑아 <strong>개조식 정리본</strong>을 만든다.</li><li><strong>원본 자료와 정리본을 나란히 놓고 같이 보면서</strong> 공부한다. <ul><li>정리본은 원본 순서대로 쓰고 쪽 번호를 달아 서로 맞춰 보기 쉽게 한다.</li></ul></li><li>비어 있는 칸(수업 중 채우는 부분)은 문맥으로 보충하고 표시해 둔다.</li></ul><h2 id="_2-헷갈리는-개념-하나씩-질문하기" tabindex="-1">2. 헷갈리는 개념 하나씩 질문하기 <a class="header-anchor" href="#_2-헷갈리는-개념-하나씩-질문하기" aria-label="Permalink to &quot;2. 헷갈리는 개념 하나씩 질문하기&quot;">​</a></h2><ul><li>정리본을 읽다가 막히는 곳마다 바로 질문한다.</li><li>한 개념이 이해 안 되면 <strong>더 기초로 내려가서</strong> 다시 묻는다. <ul><li>예: &quot;이 그래프가 왜 이렇지?&quot; → &quot;y축이 뭐지?&quot; → &quot;그 단위는 어디서 오지?&quot;</li></ul></li><li>과제나 다른 장에 적용된 사례가 있으면 <strong>그 사례에 대입해서</strong> 확인한다.</li></ul><h2 id="_3-정리-파일-저장" tabindex="-1">3. 정리 파일 저장 <a class="header-anchor" href="#_3-정리-파일-저장" aria-label="Permalink to &quot;3. 정리 파일 저장&quot;">​</a></h2><ul><li>정리본을 파일로 저장하고, 내가 한 질문과 답을 <strong>Q&amp;A로 붙인다</strong>.</li></ul><h2 id="_4-큰-흐름-잡기" tabindex="-1">4. 큰 흐름 잡기 <a class="header-anchor" href="#_4-큰-흐름-잡기" aria-label="Permalink to &quot;4. 큰 흐름 잡기&quot;">​</a></h2><ul><li>개별 내용을 이해한 뒤 <strong>장 전체의 흐름</strong>을 묻는다. (&quot;이 장은 무엇을 어떤 순서로 쌓아 가나?&quot;)</li><li>개념이 어느 장 소속인지, 사례마다 어떤 도구를 쓰는지 <strong>비교표</strong>로 확인한다.</li></ul><h2 id="_5-내-말로-요약하고-고치기-반복" tabindex="-1">5. 내 말로 요약하고 고치기 (반복) <a class="header-anchor" href="#_5-내-말로-요약하고-고치기-반복" aria-label="Permalink to &quot;5. 내 말로 요약하고 고치기 (반복)&quot;">​</a></h2><ol><li>흐름을 <strong>직접 써서</strong> 보낸다.</li><li>틀리거나 애매한 부분을 지적받는다.</li><li>막힌 개념은 2단계로 돌아가 다시 질문한다.</li><li>고친 요약을 다시 보낸다.</li><li>더 고칠 게 없을 때까지 반복한다.</li></ol><h2 id="_6-마무리" tabindex="-1">6. 마무리 <a class="header-anchor" href="#_6-마무리" aria-label="Permalink to &quot;6. 마무리&quot;">​</a></h2><ul><li>완성한 내 요약을 정리 파일 <strong>맨 위</strong>에 넣는다.</li><li>남은 용어(영어 표현, 정확한 뜻)를 확인한다.</li></ul><hr><blockquote><p>정리본 + 원본 같이 읽기 → 막히는 개념 질문(기초까지) → 파일 저장(Q&amp;A 포함) → 전체 흐름 잡기 → 내 말로 요약 → 피드백·수정 반복 → 완성본을 파일 맨 위에</p></blockquote>',16)])])}const g=t(r,[["render",o]]);export{c as __pageData,g as default};
